import urllib.request,urllib.error,json
base='https://app.ontrackegy.com/ayo/'
out=[]
for suffix in ('','api.php?action=status','app.js','style.css','audio-worklet.js'):
 try:
  req=urllib.request.Request(base+suffix,headers={'User-Agent':'OnTrack-AYO-HTTP-Smoke/1.0'})
  with urllib.request.urlopen(req,timeout=7) as r:
   raw=r.read(250000)
   item={'path':suffix or '/','http':r.status,'type':r.headers.get('content-type','')}
   if suffix=='':item['ayo_marker']=b'AYO' in raw
   if suffix=='api.php?action=status':
    data=json.loads(raw);item['config_ok']=isinstance(data.get('config'),dict);item['csrf']=bool(data.get('csrf'));item['has_inworld_key']=data.get('config',{}).get('hasInworldKey')
   out.append(item)
 except Exception as e:out.append({'path':suffix or '/','error_type':type(e).__name__,'http':getattr(e,'code',None)})
print(json.dumps(out))
